/**
 * Applies a bitwise AND operation to all numbers within a given range.
 *
 * @param {number} left - The starting point of the range (inclusive).
 * @param {number} right - The end point of the range (inclusive).
 * @return {number} - The result of the bitwise AND operation applied sequentially from left to right.
 */
function rangeBitwiseAnd(left: number, right: number): number {
    // Loop until the 'left' value is greater than or equal to 'right'
    while (left < right) {
        // Apply bitwise AND between 'right' and 'right-1' then store it back in 'right'
        // This operation removes the least significant bit of 'right'
        right &= right - 1;
    }
    // Return the value of 'right' which at this point equals the bitwise AND of the range
    return right;
}

// Determines if a number is a "happy number"
// A happy number is a number in which the sum of the square of digits eventually reaches 1
// If it enters a cycle without reaching 1, it is not a happy number
function isHappy(n: number): boolean {
    // This function calculates the sum of the squares of the digits of a given number
    const getNextNumber = (currentNumber: number): number => {
        let sumOfSquares = 0;
        while (currentNumber !== 0) {
            let digit = currentNumber % 10;
            sumOfSquares += digit ** 2;
            currentNumber = Math.floor(currentNumber / 10);
        }
        return sumOfSquares;
    };
    // Initializes two pointers for detecting cycles
    let slowPointer = n;
    let fastPointer = getNextNumber(n);
    // Uses Floyd's cycle detection algorithm to determine if a cycle exists
    while (slowPointer !== fastPointer) {
        // Moves slow pointer by one step
        slowPointer = getNextNumber(slowPointer);
        // Moves fast pointer by two steps
        fastPointer = getNextNumber(getNextNumber(fastPointer));
    }
    // If fastPointer equals 1, it means we've reached the happy number condition
    return fastPointer === 1;
}

