class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def removeElements(self, head: ListNode, val: int) -> ListNode:
        # Create a dummy node that acts as the new head of the list with a sentinel value
        dummy_node = ListNode(-1)
        dummy_node.next = head

        # Initialize a pointer to track the current node we're examining
        current_node = dummy_node

        # Iterate over the list
        while current_node.next is not None:
            # If the value of the next node is the one we want to remove
            if current_node.next.val == val:
                # Remove it by skipping the node
                current_node.next = current_node.next.next
            else:
                # Move to the next node otherwise
                current_node = current_node.next

        # Return the modified list, starting from the node after the dummy node
        return dummy_node.next

/**
 * Counts the number of prime numbers less than a non-negative number, n.
 * Implements the Sieve of Eratosthenes algorithm for finding all prime numbers in a given range.
 * @param {number} n - The upper limit (exclusive) up to which to count prime numbers.
 * @return {number} The count of prime numbers less than n.
 */
const countPrimes = (n: number): number => {
    // Initialize an array of boolean values representing the primality of each number.
    // Initially, all numbers are assumed to be prime (true), except for indices 0 and 1.
    let isPrime: boolean[] = new Array(n).fill(true);
    let primeCount: number = 0;
    // Loop through the array starting from the first prime number, 2.
    for (let i: number = 2; i < n; ++i) {
        if (isPrime[i]) {
            // Increment the prime counter when a prime number is encountered.
            ++primeCount;
            // Mark all multiples of i as non-prime (false).
            for (let multiple: number = i + i; multiple < n; multiple += i) {
                isPrime[multiple] = false;
            }
        }
    }
    // Return the count of prime numbers found.
    return primeCount;
};

// Function to check whether two strings 's' and 't' are isomorphic.
// Two strings are isomorphic if the characters in 's' can be replaced to get 't'.
function isIsomorphic(source: string, target: string): boolean {
    // Create two arrays to store the last seen positions of characters in 'source' and 'target'.
    const sourceLastSeen: number[] = new Array(256).fill(0);
    const targetLastSeen: number[] = new Array(256).fill(0);

    // Iterate over each character in the strings.
    for (let i = 0; i < source.length; ++i) {
        // Get the character code for current characters in 'source' and 'target'.
        const sourceCharCode = source.charCodeAt(i);
        const targetCharCode = target.charCodeAt(i);
        // Check if the last seen position for both characters is the same.
        // If they differ, the strings are not isomorphic.
        if (sourceLastSeen[sourceCharCode] !== targetLastSeen[targetCharCode]) {
            return false;
        }
        // Update the last seen position for both characters to the current position + 1
        // The +1 ensures that the default value of 0 is not considered a position.
        sourceLastSeen[sourceCharCode] = i + 1;
        targetLastSeen[targetCharCode] = i + 1;
    }
    // If we complete the iteration without returning false, the strings are isomorphic.
    return true;
}

