interface ListNode {
    val: number;
    next: ListNode | null;
}
/**
 * Reverses a singly linked list.
 * @param {ListNode | null} head - The head node of the linked list to be reversed
 * @return {ListNode | null} The new head of the reversed linked list
 */
function reverseList(head: ListNode | null): ListNode | null {
    // Return immediately if the list is empty
    if (head === null) {
        return head;
    }
    // Initialize pointers
    let previousNode: ListNode | null = null; // Previous node in the list
    let currentNode: ListNode | null = head;  // Current node in the list
    // Iterate through the list
    while (currentNode !== null) {
        const nextNode: ListNode | null = currentNode.next; // Next node in the list
        // Reverse the current node's pointer
        currentNode.next = previousNode;
        // Move the previous and current pointers one step forward
        previousNode = currentNode;
        currentNode = nextNode;
    }
    // By the end, previousNode is the new head of the reversed linked list
    return previousNode;
}

function canFinish(numCourses: number, prerequisites: number[][]): boolean {
    // Create an adjacency list to represent the graph of courses
    const adjacencyList: number[][] = new Array(numCourses).fill(0).map(() => []);

    // Array to store the in-degree (number of dependencies) of each course
    const inDegrees: number[] = new Array(numCourses).fill(0);

    // Fill the adjacency list and in-degree array based on prerequisites
    for (const [course, prerequisite] of prerequisites) {
        adjacencyList[prerequisite].push(course);
        inDegrees[course]++;
    }
    // Queue for courses with no prerequisites (in-degree of 0)
    const queue: number[] = [];

    // Initialize the queue with courses that have no prerequisites
    for (let i = 0; i < numCourses; ++i) {
        if (inDegrees[i] === 0) {
            queue.push(i);
        }
    }
    // Counter for the number of courses with satisfied prerequisites
    let count = 0;
    // Process the queue until it's empty
    while (queue.length) {
        // Remove the first course from the queue
        const currentCourse = queue.shift()!;

        // Increment the count of courses that can be taken
        count++;
        // Decrease the in-degree of the adjacent courses and
        // add them to the queue if they have no other prerequisites
        for (const adjacentCourse of adjacencyList[currentCourse]) {
            if (--inDegrees[adjacentCourse] === 0) {
                queue.push(adjacentCourse);
            }
        }
    }
    // Compare the count of courses taken to the total number of courses
    return count === numCourses;
}

function minSubArrayLen(target: number, nums: number[]): number {
    // Length of the input array
    const length = nums.length;
    // Initialize the sum of the current subarray
    let currentSum = 0;
    // Set an initial minimum length for the subarray to an impossible maximum (length+1)
    let minLength = length + 1;

    // Set the starting points for the sliding window
    for (let start = 0, end = 0; start < length; ++start) {
        // Add the current number to the current sum
        currentSum += nums[start];

        // While the current sum is equal or above the target,
        // adjust the window to find the minimum length
        while (currentSum >= target) {
            // Calculate the length of the current subarray
            // and update the minLength if it's smaller than the existing minLength
            minLength = Math.min(minLength, start - end + 1);

            // Subtract the first number of the current subarray
            // and move the window forward
            currentSum -= nums[end++];
        }
    }

    // If minLength was not updated, it means no valid subarray was found, so return 0
    // Otherwise, return the minLength found
    return minLength === length + 1 ? 0 : minLength;
}

function rob(nums: number[]): number {
    // Determine the length of the array.
    const numLength = nums.length;

    // Edge case: If there's only one house, return its value.
    if (numLength === 1) {
        return nums[0];
    }

    // Helper function to rob a range of houses from index l to r, inclusive.
    const robRange = (start: number, end: number): number => {
        let robPrevious = 0; // Initialize to store the maximum amount that can be robbed up to the previous house
        let robCurrent = 0;  // Initialize to store the maximum amount that can be robbed up to the current house
        // Iterate from the start index to the end index, inclusive.
        for (; start <= end; ++start) {
            let robNext = Math.max(robPrevious, robCurrent); // The next 'previous' is the max of current and previous robbed amounts.
            robCurrent = robPrevious + nums[start];          // Update the current to the sum of previous robbed amount and current house value.
            robPrevious = robNext;                           // Move the 'next' value to 'previous' for the next iteration.
        }

        // Return the maximum amount robbed between the last two houses.
        return Math.max(robPrevious, robCurrent);
    };

    // The maximum amount robbed will be the maximum of either robbing from the first house to the second-to-last house,
    // or from the second house to the last one since we cannot rob adjacent houses.
    return Math.max(robRange(0, numLength - 2), robRange(1, numLength - 1));
}

