class Solution:
    def maximalSquare(self, matrix: List[List[str]]) -> int:
        rows, cols = len(matrix), len(matrix[0]) # Get the dimensions of the matrix
        dp = [[0] * (cols + 1) for _ in range(rows + 1)] # Initialize DP table with extra row and column
        max_side_length = 0 # Maximum side length of a square of '1's
        for row in range(rows):
            for col in range(cols):
                # Check if the current element is a '1'
                if matrix[row][col] == '1':
                    # Update the DP table by considering the top, left, and top-left neighbors
                    dp[row + 1][col + 1] = min(
                        dp[row][col + 1],     # Top
                        dp[row + 1][col],     # Left
                        dp[row][col]          # Top-Left
                    ) + 1
                    # Update the max side length found so far
                    max_side_length = max(max_side_length, dp[row + 1][col + 1])

        # Return the area of the largest square
        return max_side_length * max_side_length

// Initialization of two queues to simulate a stack
let primaryQueue: number[] = [];
let secondaryQueue: number[] = [];
/**
 * Simulates pushing an element onto stack using queues.
 * @param {number} x - The element to push onto the stack.
 */
function push(x: number): void {
    // Push the element into the secondary queue
    secondaryQueue.push(x);

    // Move all elements from the primary queue to the secondary queue
    while (primaryQueue.length) {
        secondaryQueue.push(primaryQueue.shift()!);
    }

    // Swap the names of the queues, making the secondary queue the new primary queue
    [primaryQueue, secondaryQueue] = [secondaryQueue, primaryQueue];
}
/**
 * Simulates popping an element from the stack.
 * @return {number} - The element popped from the stack.
 */
function pop(): number {
    // Remove the element from the front of the primary queue
    return primaryQueue.shift()!;
}
/**
 * Retrieves the element at the top of the stack without removing it.
 * @return {number} - The element at the top of the stack.
 */
function top(): number {
    // Return the front element of the primary queue
    return primaryQueue[0];
}
/**
 * Checks if the stack is empty.
 * @return {boolean} - True if the stack is empty, false otherwise.
 */
function empty(): boolean {
    // Check if the primary queue is empty
    return primaryQueue.length === 0;
}
