/**
 * Inverts a binary tree by swapping all left and right children.
 * 
 * @param {TreeNode | null} treeRoot - The root of the binary tree to invert.
 * @return {TreeNode | null} - The new root of the inverted binary tree.
 */
function invertTree(treeRoot: TreeNode | null): TreeNode | null {
    // Recursive function to traverse the tree and swap children
    function invertNode(node: TreeNode | null): void {
        if (node === null) {
            return; // If the node is null, do nothing
        }
        [node.left, node.right] = [node.right, node.left]; // Swap the left and right children
        invertNode(node.left); // Recursively invert the left subtree
        invertNode(node.right); // Recursively invert the right subtree
    }

    invertNode(treeRoot); // Start inverting from the root node
    return treeRoot; // Return the new root after inversion
}

function majorityElement(nums: number[]): number[] {
    // Initialize counters for two potential majority elements
    let count1: number = 0;
    let count2: number = 0;
    // Initialize placeholders for two potential majority elements
    let candidate1: number = nums[0] || 0;
    let candidate2: number = nums[1] || 1;

    // Use Boyer-Moore Voting Algorithm to find potential majority elements
    for (let num of nums) {
        if (num === candidate1) {
            // If the current element is the same as candidate1, increment count1
            count1++;
        } else if (num === candidate2) {
            // If the current element is the same as candidate2, increment count2
            count2++;
        } else if (count1 === 0) {
            // If count1 is 0, replace candidate1 with the current element
            candidate1 = num;
            count1 = 1;
        } else if (count2 === 0) {
            // If count2 is 0, replace candidate2 with the current element
            candidate2 = num;
            count2 = 1;
        } else {
            // If the current element is not equal to either candidate and both counts are non-zero, decrement both counts
            count1--;
            count2--;
        }
    }
    // Initialize a result array to store the final majority elements
    const result: number[] = [];

    // Validate if the candidates are indeed majority elements
    count1 = nums.filter(num => num === candidate1).length;
    count2 = nums.filter(num => num === candidate2).length;

    // Add candidate1 to result if count is greater than a third of nums length
    if (count1 > Math.floor(nums.length / 3)) {
        result.push(candidate1);
    }
    // Add candidate2 to result if it's different from candidate1 and count is greater than a third of nums length
    if (candidate1 !== candidate2 && count2 > Math.floor(nums.length / 3)) {
        result.push(candidate2);
    }
    // Return the final result
    return result;
}

// This function checks if a given number is a power of two.
// It uses bitwise AND to determine if there is only one bit set in the binary representation.
// The number should be greater than zero since 0 is not a power of two.
// Parameters:
// n - The number to check if it is a power of two.
// Returns:
// A boolean indicating whether the number is a power of two (true) or not (false).
function isPowerOfTwo(n: number): boolean {
    // Check if 'n' is greater than 0 to avoid non-positive integers.
    // (n & (n - 1)) will be 0 for powers of two since these numbers have a single high bit.
    // For example, 4 in binary is 100, and 3 is 011. Bitwise AND is 000.
    return n > 0 && (n & (n - 1)) === 0;
}

