// Given the node to be deleted (except the tail), this function will delete the node in place.
function deleteNode(node: ListNode | null): void {
    if (node === null || node.next === null) {
        // If the node is null or it is the tail node, do nothing since deletion is not possible.
        return;
    }
    // Copy the value from the next node to the current node.
    node.val = node.next.val;
    // Bypass the next node by pointing the current node's `next` reference to the next node's `next`.
    node.next = node.next.next;
}

function productExceptSelf(nums: number[]): number[] {
    const length = nums.length; // Total number of elements in input array
    const result: number[] = new Array(length); // Initialize an array to store the result
    // Forward pass: Calculate the product of all elements to the left of each index
    for (let i = 0, productToLeft = 1; i < length; i++) {
        result[i] = productToLeft; // Set the product (initially 1)
        productToLeft *= nums[i]; // Update the productToLeft for the next index
    }
    // Backward pass: Calculate the product of all elements to the right of each index
    for (let i = length - 1, productToRight = 1; i >= 0; i--) {
        result[i] *= productToRight; // Multiply with the already stored product to the left
        productToRight *= nums[i]; // Update the productToRight for the previous index
    }
    return result; // Return the final result array
}

/**
 * Calculates the max sliding window for an array of numbers.
 * @param {number[]} nums - The input array of numbers.
 * @param {number} k - The size of the sliding window.
 * @return {number[]} - Array of the maximum numbers for each sliding window.
 */
function maxSlidingWindow(nums: number[], k: number): number[] {
    // Initialize an array to hold the maximum values for each sliding window.
    let maxValues: number[] = [];

    // Initialize a deque to store indices of elements in nums.
    // Elements in the deque are in decreasing order from the start (front) to the end (back).
    let deque: number[] = []; 

    // Iterate through nums using 'i' as the right boundary of the sliding window.
    for (let i = 0; i < nums.length; ++i) {
        // If the left boundary of the window has exceeded the left-most index in the deque,
        // remove the left-most index as it's no longer in the window.
        if (deque.length && i - k + 1 > deque[0]) {
            deque.shift();
        }

        // While the deque is not empty and the current element is greater than the
        // last element indexed in deque, remove the last element from the deque.
        // This ensures elements in the deque are always in decreasing order.
        while (deque.length && nums[deque[deque.length - 1]] <= nums[i]) {
            deque.pop();
        }

        // Add the current index to the deque.
        deque.push(i);

        // If we have hit the size of the window, append the maximum value (front of the deque)
        // to the maxValues array.
        if (i >= k - 1) {
            maxValues.push(nums[deque[0]]);
        }
    }

    // Return the array containing the maximum for each sliding window.
    return maxValues;
}

