        let normalizedCharCode = char.charCodeAt(0) - offset;
        if (normalizedCharCode < 'a'.charCodeAt(0)) {
            normalizedCharCode += 26;
        }
        return String.fromCharCode(normalizedCharCode);
    }).join('');
}
