class TreeNode {
    val: number;         // The value stored in the tree node
    left: TreeNode | null;   // Pointer to the left child
    right: TreeNode | null;  // Pointer to the right child
    // Constructor to initialize the node with default values or with given values for val, left, and right.
    constructor(val: number = 0, left: TreeNode | null = null, right: TreeNode | null = null) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}
/**
 * Searches for a node with the given value in a Binary Search Tree.
 * 
 * @param root A TreeNode representing the root of the BST.
 * @param value The value to search for in the BST.
 * @return A TreeNode pointer to the found node or null if not found.
 */
function searchBST(root: TreeNode | null, value: number): TreeNode | null {
    // Base case: if the root is null or the root's value matches the search value
    if (!root || root.val === value) {
        return root;
    }
    // If the search value is greater than the root's value, search in the right subtree.
    if (value > root.val) {
        return searchBST(root.right, value);
    }
    // If the search value is less than the root's value, search in the left subtree.
    return searchBST(root.left, value);
}

// Node structure for the binary search tree.
interface TreeNode {
  value: number;
  leftChild: TreeNode | null;
  rightChild: TreeNode | null;
}
// Function to create a new tree node with a value, and with left and right children initialized to null.
function createTreeNode(value: number, leftChild: TreeNode | null = null, rightChild: TreeNode | null = null): TreeNode {
  return {
    value: value,
    leftChild: leftChild,
    rightChild: rightChild
  };
}
/**
 * Inserts a value into a binary search tree (BST) and returns the root node of the BST.
 *
 * @param root - The root node of the tree where the value is to be inserted.
 * @param value - The value to be inserted into the BST.
 * @return The root of the BST after the insertion of the value.
 */
function insertIntoBST(root: TreeNode | null, value: number): TreeNode | null {
  // If the root is null, create a new node with the value to be inserted and return it.
  if (root === null) {
    return createTreeNode(value);
  }
  // If the value to insert is greater than the root's value, recursively insert into the right subtree.
  if (value > root.value) {
    root.rightChild = insertIntoBST(root.rightChild, value);
  } else { // If the value is less than or equal to the root's value, recursively insert into the left subtree.
    root.leftChild = insertIntoBST(root.leftChild, value);
  }
  // Return the unchanged root node.
  return root;
}

/**
 * Interface representing an array reader that supplies a `get` method to access elements at a given index.
 */
interface ArrayReader {
