// Normalizes the shape of an island to remove duplicates that are rotations or reflections of each other
function normalizeShape(shape: Point[]): Point[] {
    const shapes: Point[][] = Array.from({ length: 8 }, () => []);
    for (const point of shape) {
        const [x, y] = point;
        shapes[0].push([x, y]);
        shapes[1].push([x, -y]);
        shapes[2].push([-x, y]);
        shapes[3].push([-x, -y]);
        shapes[4].push([y, x]);
        shapes[5].push([y, -x]);
        shapes[6].push([-y, -x]);
        shapes[7].push([-y, x]);
    }

    for (const e of shapes) {
        e.sort((a, b) => a[0] === b[0] ? a[1] - b[1] : a[0] - b[0]); // Sort the points
        const [baseX, baseY] = e[0];
        e.forEach(point => {
            point[0] -= baseX;
            point[1] -= baseY;
        });
    }

    shapes.sort(); // Sort the shapes to get the canonical representation
    return shapes[0]; // Return the first shape, which is the normalized shape
}
// Performs a depth-first search to find the entire shape of an island
function depthFirstSearch(x: number, y: number, grid: number[][], shape: Point[]): void {
    const directions: number[] = [-1, 0, 1, 0, -1]; // Used to explore adjacent cells
    shape.push([x, y]);
    grid[x][y] = 0; // Mark as visited

    for (let k = 0; k < 4; ++k) {
        const nextX = x + directions[k];
        const nextY = y + directions[k + 1];
        if (nextX >= 0 && nextX < grid.length && nextY >= 0 && nextY < grid[0].length && grid[nextX][nextY] === 1) {
            depthFirstSearch(nextX, nextY, grid, shape); // Recursive DFS call
        }
    }
}
