class Solution:
    def minimumDeleteSum(self, s1: str, s2: str) -> int:
        # Calculate the length of both strings
        len_s1, len_s2 = len(s1), len(s2)

        # Initialize a 2D array to store the minimum delete sum for sub-problems
        dp = [[0] * (len_s2 + 1) for _ in range(len_s1 + 1)]

        # Pre-fill the first column with the delete sum of s1[i:]
        for i in range(1, len_s1 + 1):
            dp[i][0] = dp[i - 1][0] + ord(s1[i - 1])

        # Pre-fill the first row with the delete sum of s2[j:]
        for j in range(1, len_s2 + 1):
            dp[0][j] = dp[0][j - 1] + ord(s2[j - 1])

        # Start filling the DP table from (1,1) to (len_s1, len_s2)
        for i in range(1, len_s1 + 1):
            for j in range(1, len_s2 + 1):
                # If the current characters are equal, then no deletion is needed
                if s1[i - 1] == s2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    # Find the minimum between deleting a character from s1 or s2
                    dp[i][j] = min(
                        dp[i - 1][j] + ord(s1[i - 1]),  # Delete from s1
                        dp[i][j - 1] + ord(s2[j - 1])   # Delete from s2
                    )

        # The value at dp[len_s1][len_s2] will be the minimum delete sum for s1 and s2
        return dp[len_s1][len_s2]

function numSubarrayProductLessThanK(nums: number[], k: number): number {
    let count = 0; // Initialize the count of subarrays
    let product = 1; // Initialize the product of the current subarray
    let left = 0; // Left index of the sliding window
    // Process all numbers in the input array
    for (let right = 0; right < nums.length; ++right) {
        // Accumulate the product of the elements within the sliding window
        product *= nums[right];
        // If the product is greater than or equal to k,
        // shrink the window from the left
        while (left <= right && product >= k) {
            product /= nums[left++];
        }
        // Add the number of subarrays ending at 'right' that have a product less than k
        // This step utilizes the idea that if 'right' is the end of a valid subarray,
        // then there are 'right - left + 1' possible starting positions for subarrays
        count += right - left + 1;
    }
    // Return the total count of subarrays
    return count;
}
